create.example:
// client
const guide = kcds.characters.LocalNpc.create({
  soul: '210170d8-afb2-4cbd-9df5-da2a8e722af4',
  name: 'Guide',
  position: new kcds.math.Vector3(100, 200, 10),
});
guide.say('Follow the road to the mill.');

create.exampleCs:
// client
var guide = LocalNpc.Create(new { soul = "210170d8-afb2-4cbd-9df5-da2a8e722af4", name = "Guide", position = new Vector3(100, 200, 10) });
guide.Say("Follow the road to the mill.");

all.example:
// client
for (const figure of kcds.characters.LocalNpc.all()) {
  figure.remove();
}

all.exampleCs:
// client
foreach (var figure in LocalNpc.All())
{
    figure.Remove();
}

setPosition.example:
// client
const { Vector3 } = kcds.math;

const beside = kcds.players.LocalPlayer.position.clone().add(new Vector3(0, 2, 0));
guide.setPosition(beside, { z: 180 });

setPosition.exampleCs:
// client

var beside = LocalPlayer.Current!.Position.Clone().Add(new Vector3(0, 2, 0));
guide.SetPosition(beside, new { z = 180 });
